cd /workspace && python3 - <<'EOF'
import zipfile
from docx import Document
d = Document('inputs/offer_letter_template.docx')
def scan(paras, where):
    for p in paras:
        t = p.text
        if 'IF_' in t or 'RELOC' in t or '{{' in t:
            if 'IF_' in t or 'RELOC' in t:
                print(where, repr(t))
for p in d.paragraphs:
    if 'IF_' in p.text or 'RELOC' in p.text:
        print('body', repr(p.text))
for tbl in d.tables:
    for row in tbl.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                if 'IF_' in p.text or 'RELOC' in p.text:
                    print('cell', repr(p.text))
EOF
